<summary>Manual benchmark patch</summary>

```diff
diff --git a/src/bench/verify_script.cpp b/src/bench/verify_script.cpp
--- a/src/bench/verify_script.cpp
+++ b/src/bench/verify_script.cpp
@@ -5,6 +5,7 @@
 #include <addresstype.h>
 #include <bench/bench.h>
 #include <coins.h>
+#include <consensus/consensus.h>
 #include <key.h>
 #include <policy/policy.h>
 #include <primitives/transaction.h>
@@ -22,6 +23,7 @@
 #include <util/translation.h>

 #include <cstddef>
+#include <cstdint>
 #include <map>
 #include <span>
 #include <vector>
@@ -131,6 +133,60 @@ static void VerifyNestedIfScript(benchmark::Bench& bench)
         });
 }

+//! Maximum-size stack element that is zero except for `byte` at `pos`
+static std::vector<uint8_t> FullElement(size_t pos, uint8_t byte)
+{
+    std::vector<uint8_t> value(MAX_SCRIPT_ELEMENT_SIZE);
+    value.at(pos) = byte;
+    return value;
+}
+static constexpr size_t LAST_BYTE{MAX_SCRIPT_ELEMENT_SIZE - 1};
+
+// A single tapscript can occupy nearly the entire block weight budget
+// Both patterns cast the element to bool about once per opcode byte
+static void VerifyIfDupBench(benchmark::Bench& bench, const std::vector<uint8_t>& value, bool truthy = true)
+{
+    constexpr uint32_t SCRIPT_SIZE{MAX_BLOCK_WEIGHT - 4000};
+    CScript script;
+    script.reserve(SCRIPT_SIZE);
+    if (truthy) {
+        for (uint32_t i{0}; i < SCRIPT_SIZE / 2; ++i) {
+            script << OP_IFDUP << OP_VERIFY;
+        }
+    } else {
+        script.insert(script.end(), SCRIPT_SIZE - 2, OP_IFDUP);
+        script << OP_DROP << OP_1;
+    }
+    TaprootBuilder builder;
+    builder.Add(0, script, TAPROOT_LEAF_TAPSCRIPT).Finalize(XOnlyPubKey::NUMS_H);
+    const CScript script_pub_key{GetScriptForDestination(builder.GetOutput())};
+    const auto spend_data{builder.GetSpendData()};
+    CScriptWitness witness;
+    witness.stack = {value, ToByteVector(script), *spend_data.scripts.begin()->second.begin()};
+    assert(script.size() == SCRIPT_SIZE);
+    assert(value.size() <= MAX_SCRIPT_ELEMENT_SIZE);
+
+    bench.unit("script").run([&] {
+        ScriptError error;
+        const bool success{VerifyScript({}, script_pub_key, &witness, STANDARD_SCRIPT_VERIFY_FLAGS, BaseSignatureChecker(), &error)};
+        assert(success && error == SCRIPT_ERR_OK);
+    });
+}
+
+static void VerifyIfDupVerifyFullLast(benchmark::Bench& bench) { VerifyIfDupBench(bench, FullElement(LAST_BYTE, 1)); }
+static void VerifyIfDupVerifyFullFirst(benchmark::Bench& bench) { VerifyIfDupBench(bench, FullElement(0, 1)); }
+static void VerifyIfDupVerifyFullZeroLastWord(benchmark::Bench& bench) { VerifyIfDupBench(bench, FullElement(LAST_BYTE - sizeof(uint64_t), 1)); }
+static void VerifyIfDupVerifyTrue(benchmark::Bench& bench) { VerifyIfDupBench(bench, {1}); }
+static void VerifyIfDupFullZero(benchmark::Bench& bench) { VerifyIfDupBench(bench, FullElement(0, 0), /*truthy=*/false); }
+static void VerifyIfDupFullNegativeZero(benchmark::Bench& bench) { VerifyIfDupBench(bench, FullElement(LAST_BYTE, 0x80), /*truthy=*/false); }
+
+BENCHMARK(VerifyIfDupVerifyFullLast);
+BENCHMARK(VerifyIfDupVerifyFullFirst);
+BENCHMARK(VerifyIfDupVerifyFullZeroLastWord);
+BENCHMARK(VerifyIfDupVerifyTrue);
+BENCHMARK(VerifyIfDupFullZero);
+BENCHMARK(VerifyIfDupFullNegativeZero);
+
 BENCHMARK(VerifyScriptP2WPKH);
 BENCHMARK(VerifyScriptP2TR_KeyPath);
 BENCHMARK(VerifyScriptP2TR_ScriptPath);
```
</details>

Part of #36692. Please view this PR in context of changes like https://github.com/bitcoin/bitcoin/pull/36694.

`CTransaction` gains a constructor that allows direct declarative construction as an alternative to building through `CMutableTransaction`. `CTxIn`'s constructors gain an optional argument to pass the script witness.

It is a conscious decision that `vin/vout` are passed as generic input ranges and that only *their elements* are copied/moved.
Passing the `std::vector` by value and then moving the *container itself* into place would allow the following:

```cpp
std::vector<CTxIn> inputs = ...;
CTxIn& backdoor = inputs.back();

const CTransaction tx{std::move(inputs), ...};

backdoor = ...; // <- modify `tx`, potentially breaking its invariant
```

